from __future__ import annotations
import base64
import gzip
from pathlib import Path
import json

ROOT = Path.cwd()
HEADER_B64 = ''
WORKFLOW_B64 = ''
REPLACEMENTS = json.loads('[...[truncated]...')


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    source = target.read_text(encoding="utf-8")
    count = source.count(old)
    if count != 1:
        raise RuntimeError(f"{path}: expected one match, found {count}")
    target.write_text(source.replace(old, new, 1), encoding="utf-8", newline="\n")


header = gzip.decompress(base64.b64decode(HEADER_B64)).decode("utf-8")
if len(header) != 25753:
    raise RuntimeError("unexpected replacement header length")
(ROOT / "hp/native/src/sh_stats_session_policy_fix.h").write_text(
    header, encoding="utf-8", newline="\n"
)

for path, old, new in REPLACEMENTS:
    replace_once(path, old, new)

workflow = base64.b64decode(WORKFLOW_B64).decode("utf-8")
(ROOT / ".github/workflows/video-ci.yml").write_text(
    workflow, encoding="utf-8", newline="\n"
)
self_path = ROOT / ".github/scripts/apply_stationhead_stats_fix.py"
if self_path.exists():
    self_path.unlink()
